-- New activity starts at activation; no history replay or points reassignment.
BEGIN;
CREATE TABLE IF NOT EXISTS achievement_translation_receipts (
  user_id TEXT NOT NULL, translation_id BIGINT NOT NULL CHECK (translation_id > 0),
  PRIMARY KEY(user_id, translation_id)
);
CREATE TABLE IF NOT EXISTS achievement_activity (user_id TEXT PRIMARY KEY, state JSONB NOT NULL);
ALTER TABLE achievements DROP CONSTRAINT IF EXISTS achievements_metric_check;
ALTER TABLE achievements ADD CONSTRAINT achievements_metric_check CHECK (metric IN ('TRANSLATIONS_COMPLETED','SIGNS_LEARNED','ALPHABET_COMPLETED','SESSIONS_COMPLETED','CATALOG_REQUIREMENT','ACTIVE_SECONDS','VOICE_COMPLETED','FAVORITE_WORD','DISTINCT_WORDS','LETTERS_VIEWED','BOTH_MODES','TRANSLATION_DAYS','WORD_CATEGORIES'));
ALTER TABLE achievements DROP CONSTRAINT IF EXISTS ck_achievement_available_measurement;
ALTER TABLE achievements DROP CONSTRAINT IF EXISTS ck_achievement_activation;
ALTER TABLE achievements ADD CONSTRAINT ck_achievement_available_measurement CHECK (availability <> 'available' OR metric IN ('TRANSLATIONS_COMPLETED','ACTIVE_SECONDS','VOICE_COMPLETED','FAVORITE_WORD','DISTINCT_WORDS','LETTERS_VIEWED','BOTH_MODES','TRANSLATION_DAYS','WORD_CATEGORIES'));
ALTER TABLE achievements ADD CONSTRAINT ck_achievement_activation CHECK (NOT is_active OR (availability='available' AND metric <> 'CATALOG_REQUIREMENT' AND target_count > 0));
COMMIT;
